cat > Views/Partials/blockgrid/Components/postListBlock.cshtml <<'EOF'
@inherits UmbracoViewPage<BlockGridItem<PostListBlock>>
@{
    var page = UmbracoContext.PublishedRequest?.PublishedContent;
    var posts = page?.Children<BlogPost>()?
        .OrderByDescending(p => p.PublishDate)
        .Select(p => new PostTeaserModel
        {
            Title = string.IsNullOrWhiteSpace(p.Title) ? p.Name : p.Title,
            Summary = p.Summary,
            Url = p.Url(),
            ImageUrl = p.HeroImage?.GetCropUrl(width: 800, height: 450),
            Author = p.Author,
            PublishDate = p.PublishDate == default ? null : p.PublishDate,
        })
        .ToList() ?? [];

    var model = new PostListModel
    {
        Heading = Model.Content.Heading,
        Posts = posts,
    };
}
@await Component.InvokeAsync("PostList", new { model })
EOF
cat > Views/Shared/Components/Hero/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.HeroModel
<section class="relative overflow-hidden rounded-3xl bg-slate-900 text-white min-h-[24rem] flex items-end">
    @if (!string.IsNullOrEmpty(Model.ImageUrl))
    {
        <img src="@Model.ImageUrl" alt="" class="absolute inset-0 h-full w-full object-cover opacity-60" />
    }
    <div class="relative p-8 md:p-14 max-w-3xl">
        <h1 class="text-4xl md:text-6xl font-bold tracking-tight">@Model.Heading</h1>
        @if (!string.IsNullOrWhiteSpace(Model.Subheading))
        {
            <p class="mt-4 text-lg md:text-xl text-slate-200">@Model.Subheading</p>
        }
    </div>
</section>
EOF
cat > Views/Shared/Components/RichText/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.RichTextModel
<div class="rte max-w-3xl mx-auto">
    @Html.Raw(Model.Html)
</div>
EOF
cat > Views/Shared/Components/Image/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.ImageModel
@if (!string.IsNullOrEmpty(Model.ImageUrl))
{
    <figure class="max-w-4xl mx-auto">
        <img src="@Model.ImageUrl" alt="@(Model.AltText ?? "")" class="w-full rounded-2xl" loading="lazy" />
        @if (!string.IsNullOrWhiteSpace(Model.Caption))
        {
            <figcaption class="mt-3 text-center text-sm text-slate-500">@Model.Caption</figcaption>
        }
    </figure>
}
EOF
cat > Views/Shared/Components/Quote/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.QuoteModel
<blockquote class="max-w-3xl mx-auto border-l-4 border-indigo-500 pl-6 py-2">
    <p class="text-2xl md:text-3xl font-medium leading-snug text-slate-800">&ldquo;@Model.Quote&rdquo;</p>
    @if (!string.IsNullOrWhiteSpace(Model.Attribution))
    {
        <footer class="mt-3 text-sm uppercase tracking-wide text-slate-500">&mdash; @Model.Attribution</footer>
    }
</blockquote>
EOF
cat > Views/Shared/Components/PostList/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.PostListModel
<section>
    @if (!string.IsNullOrWhiteSpace(Model.Heading))
    {
        <h2 class="text-3xl font-bold tracking-tight mb-8">@Model.Heading</h2>
    }
    @if (Model.Posts.Count == 0)
    {
        <p class="text-slate-500">No posts yet.</p>
    }
    else
    {
        <ul class="grid gap-8 md:grid-cols-2">
            @foreach (var post in Model.Posts)
            {
                <li class="group rounded-2xl border border-slate-200 bg-white overflow-hidden shadow-sm hover:shadow-md transition">
                    <a href="@post.Url" class="block">
                        @if (!string.IsNullOrEmpty(post.ImageUrl))
                        {
                            <img src="@post.ImageUrl" alt="" class="aspect-video w-full object-cover" loading="lazy" />
                        }
                        <div class="p-6">
                            <p class="text-xs uppercase tracking-wide text-slate-500">
                                @if (post.PublishDate is { } date)
                                {
                                    <time datetime="@date.ToString("yyyy-MM-dd")">@date.ToString("d MMMM yyyy")</time>
                                }
                                @if (!string.IsNullOrWhiteSpace(post.Author))
                                {
                                    <span> &middot; @post.Author</span>
                                }
                            </p>
                            <h3 class="mt-2 text-xl font-semibold group-hover:text-indigo-600">@post.Title</h3>
                            @if (!string.IsNullOrWhiteSpace(post.Summary))
                            {
                                <p class="mt-2 text-slate-600">@post.Summary</p>
                            }
                        </div>
                    </a>
                </li>
            }
        </ul>
    }
</section>
EOF
echo done

